package com.github.diogogdias.crimescene;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(CrimeScenePlugin.CONFIG_GROUP)
public interface CrimeSceneConfig extends Config
{
	@ConfigItem(
		keyName = "markFriends",
		name = "Mark friends",
		description = "Mark the tile when a player on your friends list dies",
		position = 0
	)
	default boolean markFriends()
	{
		return true;
	}

	@ConfigItem(
		keyName = "markFriendsChat",
		name = "Mark friends chat",
		description = "Also mark friends chat members",
		position = 1
	)
	default boolean markFriendsChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "markClanMembers",
		name = "Mark clan members",
		description = "Also mark clan members",
		position = 2
	)
	default boolean markClanMembers()
	{
		return false;
	}

	@ConfigItem(
		keyName = "markOtherPlayers",
		name = "Mark other players",
		description = "Mark the tile where any other player dies, not just friends, friends chat or clan members",
		position = 3
	)
	default boolean markOtherPlayers()
	{
		return false;
	}

	@ConfigItem(
		keyName = "markSelfDeaths",
		name = "Mark my own deaths",
		description = "Also mark the tile where you die (works anywhere, no one else needs to witness it)",
		position = 4
	)
	default boolean markSelfDeaths()
	{
		return true;
	}

	@ConfigItem(
		keyName = "markNpcs",
		name = "Mark NPCs",
		description = "Also mark the tile where any NPC dies",
		position = 5
	)
	default boolean markNpcs()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showSkull",
		name = "Show skull",
		description = "Draw the in-game skull sprite on the death tile",
		position = 6
	)
	default boolean showSkull()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "borderColor",
		name = "Border colour",
		description = "Tile border colour",
		position = 7
	)
	default Color borderColor()
	{
		return Color.RED;
	}

	@Alpha
	@ConfigItem(
		keyName = "fillColor",
		name = "Fill colour",
		description = "Tile fill colour",
		position = 8
	)
	default Color fillColor()
	{
		return new Color(255, 0, 0, 50);
	}

	@Alpha
	@ConfigItem(
		keyName = "fontColor",
		name = "Font colour",
		description = "Colour of the death number drawn on the tile",
		position = 9
	)
	default Color fontColor()
	{
		return Color.WHITE;
	}

	@Range(min = 8, max = 40)
	@ConfigItem(
		keyName = "fontSize",
		name = "Number size",
		description = "Font size of the death number",
		position = 10
	)
	default int fontSize()
	{
		return 14;
	}

	@ConfigItem(
		keyName = "clearHotkey",
		name = "Clear-all hotkey",
		description = "Hotkey to remove every marker (assign a key, and make sure the game has focus)",
		position = 11
	)
	default Keybind clearHotkey()
	{
		return Keybind.NOT_SET;
	}
}

package com.github.diogogdias.crimescene;

import java.util.LinkedHashMap;
import java.util.Map;
import lombok.Getter;

@Getter
class CrimeSceneMarker
{
	private int x;
	private int y;
	private int plane;
	private int number;
	private Map<String, Integer> players = new LinkedHashMap<>();
	private Map<String, Integer> npcs = new LinkedHashMap<>();

	CrimeSceneMarker()
	{
	}

	CrimeSceneMarker(int x, int y, int plane)
	{
		this.x = x;
		this.y = y;
		this.plane = plane;
	}

	/**
	 * Removes a tracked name from this tile, decrementing the death count by the removed total.
	 *
	 * @return the number of deaths removed (0 if the name was not present)
	 */
	int remove(String name, boolean npc)
	{
		Map<String, Integer> source = npc ? npcs : players;
		if (source == null)
		{
			return 0;
		}

		Integer removed = source.remove(name);
		if (removed == null)
		{
			return 0;
		}

		number -= removed;
		return removed;
	}

	boolean isEmpty()
	{
		return number <= 0;
	}

	void record(String name, boolean npc)
	{
		number++;
		if (name == null)
		{
			return;
		}

		if (npc)
		{
			if (npcs == null)
			{
				npcs = new LinkedHashMap<>();
			}
			npcs.merge(name, 1, Integer::sum);
		}
		else
		{
			if (players == null)
			{
				players = new LinkedHashMap<>();
			}
			players.merge(name, 1, Integer::sum);
		}
	}
}

package com.github.diogogdias.crimescene;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.image.BufferedImage;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ImageUtil;

class CrimeSceneOverlay extends Overlay
{
	private final Client client;
	private final CrimeScenePlugin plugin;
	private final CrimeSceneConfig config;
	private final TooltipManager tooltipManager;

	private static final int SKULL_SCALE_PERCENT = 25;

	private BufferedImage scaledSkull;
	private BufferedImage scaledSource;
	private int scaledPercent = -1;

	@Inject
	CrimeSceneOverlay(Client client, CrimeScenePlugin plugin, CrimeSceneConfig config, TooltipManager tooltipManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<WorldPoint, CrimeSceneMarker> markers = plugin.getMarkers();
		if (markers.isEmpty())
		{
			return null;
		}

		int plane = client.getPlane();
		Color border = config.borderColor();
		Color fill = config.fillColor();
		Color font = config.fontColor();
		BufferedImage skull = config.showSkull()
			? getScaledSkull(plugin.getSkullImage(), SKULL_SCALE_PERCENT)
			: null;
		Point mouse = client.getMouseCanvasPosition();
		graphics.setFont(graphics.getFont().deriveFont((float) config.fontSize()));
		graphics.setStroke(new BasicStroke(2));
		boolean instanced = client.isInInstancedRegion();

		for (Map.Entry<WorldPoint, CrimeSceneMarker> entry : markers.entrySet())
		{
			WorldPoint worldPoint = entry.getKey();
			CrimeSceneMarker marker = entry.getValue();

			if (instanced)
			{
				// A template chunk may appear at several spots in the instance; draw at each
				for (WorldPoint instancePoint : WorldPoint.toLocalInstance(client, worldPoint))
				{
					drawMarker(graphics, instancePoint, plane, marker, border, fill, font, skull, mouse);
				}
			}
			else
			{
				drawMarker(graphics, worldPoint, plane, marker, border, fill, font, skull, mouse);
			}
		}

		return null;
	}

	private void drawMarker(Graphics2D graphics, WorldPoint worldPoint, int plane, CrimeSceneMarker marker,
		Color border, Color fill, Color font, BufferedImage skull, Point mouse)
	{
		if (worldPoint.getPlane() != plane)
		{
			return;
		}

		LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
		if (localPoint == null)
		{
			return;
		}

		Polygon poly = Perspective.getCanvasTilePoly(client, localPoint);
		if (poly != null)
		{
			graphics.setColor(fill);
			graphics.fill(poly);
			graphics.setColor(border);
			graphics.draw(poly);

			if (mouse != null && poly.contains(mouse.getX(), mouse.getY()))
			{
				tooltipManager.add(new Tooltip(buildTooltip(marker)));
			}
		}

		boolean drawSkull = skull != null;
		if (drawSkull)
		{
			OverlayUtil.renderImageLocation(client, graphics, localPoint, skull, 0);
		}

		String text = String.valueOf(marker.getNumber());
		Point textLocation = Perspective.getCanvasTextLocation(client, graphics, localPoint, text, 0);
		if (textLocation != null)
		{
			int yOffset = drawSkull ? skull.getHeight() / 2 + 4 : 0;
			Point numberLocation = new Point(textLocation.getX(), textLocation.getY() - yOffset);
			OverlayUtil.renderTextLocation(graphics, numberLocation, text, font);
		}
	}

	private BufferedImage getScaledSkull(BufferedImage source, int percent)
	{
		if (source == null)
		{
			return null;
		}

		if (scaledSkull == null || scaledSource != source || scaledPercent != percent)
		{
			int width = Math.max(1, source.getWidth() * percent / 100);
			int height = Math.max(1, source.getHeight() * percent / 100);
			scaledSkull = ImageUtil.resizeImage(source, width, height);
			scaledSource = source;
			scaledPercent = percent;
		}

		return scaledSkull;
	}

	private static String buildTooltip(CrimeSceneMarker marker)
	{
		StringBuilder builder = new StringBuilder();
		appendVictims(builder, marker.getPlayers());
		appendVictims(builder, marker.getNpcs());
		return builder.toString();
	}

	private static void appendVictims(StringBuilder builder, Map<String, Integer> victims)
	{
		if (victims == null)
		{
			return;
		}

		for (Map.Entry<String, Integer> victim : victims.entrySet())
		{
			if (builder.length() > 0)
			{
				builder.append("</br>");
			}
			builder.append(victim.getKey()).append(": ").append(victim.getValue());
		}
	}
}

package com.github.diogogdias.crimescene;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.Map;
import java.util.function.BiConsumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;

class CrimeScenePanel extends PluginPanel
{
	private static final Color GOLD = new Color(255, 215, 0);
	private static final Color SILVER = new Color(192, 192, 192);
	private static final Color BRONZE = new Color(205, 127, 50);
	private static final String PLAYERS_CARD = "players";
	private static final String NPCS_CARD = "npcs";

	private final JPanel playersList = new JPanel();
	private final JPanel npcsList = new JPanel();
	private final JLabel playersTab = new JLabel("Players", SwingConstants.CENTER);
	private final JLabel npcsTab = new JLabel("NPCs", SwingConstants.CENTER);
	private final CardLayout cardLayout = new CardLayout();
	private final JPanel cards = new JPanel(cardLayout);
	private Runnable clearCallback;
	private BiConsumer<String, Boolean> deleteCallback;

	CrimeScenePanel()
	{
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new BorderLayout(0, 10));
		setBorder(BorderFactory.createEmptyBorder(12, 10, 12, 10));

		add(buildHeader(), BorderLayout.NORTH);
		add(buildBody(), BorderLayout.CENTER);
		add(buildClearButton(), BorderLayout.SOUTH);

		selectTab(true);
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout(8, 0));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel icon = new JLabel(new ImageIcon(ImageUtil.loadImageResource(CrimeScenePanel.class, "panel_icon.png")));

		JLabel title = new JLabel("Crime Scene");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);

		header.add(icon, BorderLayout.WEST);
		header.add(title, BorderLayout.CENTER);
		return header;
	}

	private JPanel buildBody()
	{
		playersList.setLayout(new BoxLayout(playersList, BoxLayout.Y_AXIS));
		playersList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		npcsList.setLayout(new BoxLayout(npcsList, BoxLayout.Y_AXIS));
		npcsList.setBackground(ColorScheme.DARK_GRAY_COLOR);

		setupTab(playersTab, true);
		setupTab(npcsTab, false);

		JPanel tabBar = new JPanel(new GridLayout(1, 2));
		tabBar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		tabBar.add(playersTab);
		tabBar.add(npcsTab);

		cards.setBackground(ColorScheme.DARK_GRAY_COLOR);
		cards.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		cards.add(north(playersList), PLAYERS_CARD);
		cards.add(north(npcsList), NPCS_CARD);

		JPanel body = new JPanel(new BorderLayout());
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		body.add(tabBar, BorderLayout.NORTH);
		body.add(cards, BorderLayout.CENTER);
		return body;
	}

	private void setupTab(JLabel tab, boolean players)
	{
		tab.setOpaque(true);
		tab.setFont(FontManager.getRunescapeBoldFont());
		tab.setCursor(new Cursor(Cursor.HAND_CURSOR));
		tab.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				selectTab(players);
			}
		});
	}

	private void selectTab(boolean players)
	{
		cardLayout.show(cards, players ? PLAYERS_CARD : NPCS_CARD);
		styleTab(playersTab, players);
		styleTab(npcsTab, !players);
	}

	private static void styleTab(JLabel tab, boolean selected)
	{
		tab.setBackground(selected ? ColorScheme.DARK_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		tab.setForeground(selected ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		tab.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 2, 0,
				selected ? ColorScheme.BRAND_ORANGE : ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(7, 0, 7, 0)));
	}

	private static JPanel north(JPanel list)
	{
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(list, BorderLayout.NORTH);
		return wrapper;
	}

	private JButton buildClearButton()
	{
		JButton button = new JButton("Clear all markers");
		button.setFocusPainted(false);
		button.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		button.addActionListener(e ->
		{
			if (clearCallback != null)
			{
				clearCallback.run();
			}
		});
		return button;
	}

	void setClearCallback(Runnable clearCallback)
	{
		this.clearCallback = clearCallback;
	}

	void setDeleteCallback(BiConsumer<String, Boolean> deleteCallback)
	{
		this.deleteCallback = deleteCallback;
	}

	void update(List<Map.Entry<String, Integer>> players, List<Map.Entry<String, Integer>> npcs)
	{
		SwingUtilities.invokeLater(() ->
		{
			populate(playersList, players, false);
			populate(npcsList, npcs, true);
		});
	}

	private void populate(JPanel listPanel, List<Map.Entry<String, Integer>> leaderboard, boolean npcs)
	{
		listPanel.removeAll();

		if (leaderboard.isEmpty())
		{
			JLabel empty = new JLabel("No deaths recorded yet", SwingConstants.CENTER);
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setBorder(BorderFactory.createEmptyBorder(16, 0, 0, 0));
			empty.setAlignmentX(Component.CENTER_ALIGNMENT);
			listPanel.add(empty);
		}
		else
		{
			int rank = 1;
			for (Map.Entry<String, Integer> entry : leaderboard)
			{
				if (rank > 1)
				{
					listPanel.add(Box.createRigidArea(new Dimension(0, 4)));
				}
				listPanel.add(buildRow(rank++, entry.getKey(), entry.getValue(), npcs));
			}
		}

		listPanel.revalidate();
		listPanel.repaint();
	}

	private JPanel buildRow(int rank, String name, int deaths, boolean npc)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel rankLabel = new JLabel(String.valueOf(rank));
		rankLabel.setFont(FontManager.getRunescapeBoldFont());
		rankLabel.setForeground(rankColor(rank));
		rankLabel.setPreferredSize(new Dimension(18, 0));

		JLabel nameLabel = new JLabel(name);
		nameLabel.setForeground(Color.WHITE);

		JLabel countLabel = new JLabel(String.valueOf(deaths));
		countLabel.setFont(FontManager.getRunescapeBoldFont());
		countLabel.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);

		JPanel left = new JPanel(new BorderLayout(8, 0));
		left.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		left.add(rankLabel, BorderLayout.WEST);
		left.add(nameLabel, BorderLayout.CENTER);

		row.add(left, BorderLayout.CENTER);
		row.add(countLabel, BorderLayout.EAST);

		JPopupMenu popup = new JPopupMenu();
		JMenuItem delete = new JMenuItem("Delete tracker");
		delete.addActionListener(e ->
		{
			if (deleteCallback != null)
			{
				deleteCallback.accept(name, npc);
			}
		});
		popup.add(delete);

		// Set on the row and let the child components inherit so a right-click anywhere shows the menu
		row.setComponentPopupMenu(popup);
		left.setInheritsPopupMenu(true);
		rankLabel.setInheritsPopupMenu(true);
		nameLabel.setInheritsPopupMenu(true);
		countLabel.setInheritsPopupMenu(true);

		return row;
	}

	private static Color rankColor(int rank)
	{
		switch (rank)
		{
			case 1:
				return GOLD;
			case 2:
				return SILVER;
			case 3:
				return BRONZE;
			default:
				return ColorScheme.LIGHT_GRAY_COLOR;
		}
	}
}

package com.github.diogogdias.crimescene;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Crime Scene",
	description = "Marks the tile where each friend dies and labels it with that tile's death count",
	tags = {"death", "friend", "marker", "tile", "pvm", "pvp"}
)
public class CrimeScenePlugin extends Plugin
{
	static final String CONFIG_GROUP = "crime-scene";
	private static final String MARKERS_KEY = "markers";
	private static final Type MARKER_LIST_TYPE = new TypeToken<List<CrimeSceneMarker>>()
	{
	}.getType();

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CrimeSceneOverlay overlay;

	@Inject
	private CrimeSceneConfig config;

	@Inject
	private KeyManager keyManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private CrimeScenePanel panel;

	@Getter(AccessLevel.PACKAGE)
	private final Map<WorldPoint, CrimeSceneMarker> markers = new ConcurrentHashMap<>();

	@Getter(AccessLevel.PACKAGE)
	private volatile BufferedImage skullImage;

	private NavigationButton navButton;

	private final HotkeyListener clearHotkey = new HotkeyListener(() -> config.clearHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			clearMarkers();
		}
	};

	@Override
	protected void startUp()
	{
		loadMarkers();
		spriteManager.getSpriteAsync(SpriteID.ICON_SKULL, 0, image -> skullImage = image);
		overlayManager.add(overlay);
		keyManager.registerKeyListener(clearHotkey);

		navButton = NavigationButton.builder()
			.tooltip("Crime Scene")
			.icon(ImageUtil.loadImageResource(CrimeScenePlugin.class, "panel_icon.png"))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		panel.setClearCallback(this::clearMarkers);
		panel.setDeleteCallback(this::deleteTracker);
		refreshPanel();

		log.debug("Crime Scene started");
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(clearHotkey);
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		markers.clear();
		skullImage = null;
		log.debug("Crime Scene stopped");
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor actor = event.getActor();
		boolean isPlayer = actor instanceof Player;

		boolean mark;
		if (!isPlayer)
		{
			mark = config.markNpcs();
		}
		else if (actor == client.getLocalPlayer())
		{
			mark = config.markSelfDeaths();
		}
		else
		{
			mark = isTracked((Player) actor);
		}

		if (!mark)
		{
			return;
		}

		WorldPoint location;
		if (client.isInInstancedRegion())
		{
			// In instances, store the template chunk coordinate so the marker maps back on return
			LocalPoint local = actor.getLocalLocation();
			location = local != null ? WorldPoint.fromLocalInstance(client, local) : null;
		}
		else
		{
			location = actor.getWorldLocation();
		}

		if (location == null)
		{
			return;
		}

		CrimeSceneMarker marker = markers.computeIfAbsent(location,
			point -> new CrimeSceneMarker(point.getX(), point.getY(), point.getPlane()));
		marker.record(actor.getName(), !isPlayer);
		saveMarkers();
		refreshPanel();
	}

	private boolean isTracked(Player player)
	{
		String name = player.getName();
		if (name == null)
		{
			return false;
		}

		if (config.markOtherPlayers())
		{
			return true;
		}

		if (config.markFriends() && client.isFriended(name, false))
		{
			return true;
		}

		if (config.markFriendsChat() && player.isFriendsChatMember())
		{
			return true;
		}

		return config.markClanMembers() && player.isClanMember();
	}

	void clearMarkers()
	{
		markers.clear();
		configManager.unsetConfiguration(CONFIG_GROUP, MARKERS_KEY);
		refreshPanel();
	}

	/**
	 * Removes a single tracked name from every tile, dropping any tile left with no deaths.
	 *
	 * @param npcs true to delete from the NPC leaderboard, false for the player leaderboard
	 */
	void deleteTracker(String name, boolean npcs)
	{
		boolean changed = false;
		Iterator<CrimeSceneMarker> it = markers.values().iterator();
		while (it.hasNext())
		{
			CrimeSceneMarker marker = it.next();
			if (marker.remove(name, npcs) > 0)
			{
				changed = true;
				if (marker.isEmpty())
				{
					it.remove();
				}
			}
		}

		if (changed)
		{
			saveMarkers();
			refreshPanel();
		}
	}

	/**
	 * Aggregates total deaths per name across every marked tile, ranked highest first.
	 *
	 * @param npcs true for the NPC leaderboard, false for the player leaderboard
	 */
	List<Map.Entry<String, Integer>> getLeaderboard(boolean npcs)
	{
		Map<String, Integer> totals = new HashMap<>();
		for (CrimeSceneMarker marker : markers.values())
		{
			Map<String, Integer> source = npcs ? marker.getNpcs() : marker.getPlayers();
			if (source != null)
			{
				source.forEach((name, count) -> totals.merge(name, count, Integer::sum));
			}
		}

		return totals.entrySet().stream()
			.sorted((a, b) -> Integer.compare(b.getValue(), a.getValue()))
			.collect(Collectors.toList());
	}

	private void refreshPanel()
	{
		panel.update(getLeaderboard(false), getLeaderboard(true));
	}

	private void loadMarkers()
	{
		markers.clear();

		String json = configManager.getConfiguration(CONFIG_GROUP, MARKERS_KEY);
		if (json != null && !json.isEmpty())
		{
			List<CrimeSceneMarker> stored = gson.fromJson(json, MARKER_LIST_TYPE);
			if (stored != null)
			{
				for (CrimeSceneMarker marker : stored)
				{
					markers.put(new WorldPoint(marker.getX(), marker.getY(), marker.getPlane()), marker);
				}
			}
		}
	}

	private void saveMarkers()
	{
		List<CrimeSceneMarker> stored = new ArrayList<>(markers.values());
		configManager.setConfiguration(CONFIG_GROUP, MARKERS_KEY, gson.toJson(stored, MARKER_LIST_TYPE));
	}

	@Provides
	CrimeSceneConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CrimeSceneConfig.class);
	}
}

